242	    @Override
243	    @Transactional
244	    public void saveOwner(Owner owner) throws DataAccessException {
245	        if (owner.getCustomerCode() == null) {
246	            owner.setCustomerCode(generateCustomerCode(owner));
247	        }
248	        ownerRepository.save(owner);
249	
250	    }
251	
252	    /** Fixed city-to-region table used to derive an owner's region for its customer code. */
253	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
254	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
255	
256	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
257	     *  when deriving an owner's region. */
258	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
259	        "NSW", new int[] {2000, 2099},
260	        "VIC", new int[] {3000, 3099},
261	        "QLD", new int[] {4000, 4099});
262	
263	    /**
264	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
265	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
266	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
267	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
268	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
269	     *
270	     * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code '-<n>'}
271	     * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
272	     * always receive distinct customer codes.
273	     */
274	    private String generateCustomerCode(Owner owner) {
275	        String base = String.format("%s-%s", deriveRegion(owner), hash8(owner));
276	        Set<String> existing = ownerRepository.findAll().stream()
277	            .map(Owner::getCustomerCode)
278	            .filter(Objects::nonNull)
279	            .collect(Collectors.toSet());
280	        if (!existing.contains(base)) {
281	            return base;
282	        }
283	        for (int n = 2; ; n++) {
284	            String candidate = base + "-" + n;
285	            if (!existing.contains(candidate)) {
286	                return candidate;
287	            }
288	        }
289	    }
290	
291	    /**
292	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
293	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
294	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
295	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
296	     * city is not in the table.
297	     */
298	    private static String deriveRegion(Owner owner) {
299	        String postcode = owner.getPostcode();
300	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
301	            int value = Integer.parseInt(postcode);
302	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
303	                int[] range = entry.getValue();
304	                if (value >= range[0] && value <= range[1]) {
305	                    return entry.getKey();
306	                }
307	            }
308	        }
309	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
310	    }
311	
312	    /**
313	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
314	     * digest over its normalized telephone concatenated with its last name.
315	     */
316	    private static String hash8(Owner owner) {
317	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
318	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
319	        String seed = telephone + lastName;
320	        try {
321	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
322	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
323	            StringBuilder sb = new StringBuilder(hash.length * 2);
324	            for (byte b : hash) {
325	                sb.append(String.format("%02X", b));
326	            }
327	            return sb.substring(0, 8);
328	        }
329	        catch (NoSuchAlgorithmException e) {
330	            throw new IllegalStateException("SHA-256 not available", e);
331	        }
332	    }
333	
334	    /**
335	     * Whether any existing owner has the given derived identity key. This is the single basis for
336	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
337	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
338	     */
339	    @Override
340	    @Transactional(readOnly = true)
341	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
342	        if (identityKey == null) {
343	            return false;
344	        }
345	        return ownerRepository.findAll().stream()
346	            .filter(existing -> !existing.isDeleted())
347	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
348	    }
349	
350	    /**
351	     * Finds the id of an existing owner that {@code owner} soft-matches (a possible duplicate): one
352	     * that shares its lastName (case-insensitive) and postcode while carrying a <i>different</i>
353	     * telephone. This is a weaker match than the hard-duplicate identity key, so it is only meaningful
354	     * for an owner that is not itself a hard duplicate. When several owners match, the one with the
355	     * lowest id is returned; {@code null} is returned when there is no match (or lastName/postcode is
356	     * absent), meaning the owner is not a possible duplicate.
357	     */
358	    @Override
359	    @Transactional(readOnly = true)
360	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
361	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
362	            return null;
363	        }
364	        String lastName = owner.getLastName();
365	        String postcode = owner.getPostcode();
366	        String telephone = owner.getTelephone();
367	        return ownerRepository.findAll().stream()
368	            .filter(existing -> !existing.isDeleted())
369	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName())
370	                && postcode.equals(existing.getPostcode())
371	                && !Objects.equals(telephone, existing.getTelephone()))
372	            .map(Owner::getId)
373	            .filter(Objects::nonNull)
374	            .min(Comparator.naturalOrder())
375	            .orElse(null);
376	    }
377	
378	    /**
379	     * Counts the existing owners whose firstName and lastName match the given values
380	     * case-insensitively. Used to record an owner's namesake count at creation time.
381	     */
382	    @Override
383	    @Transactional(readOnly = true)
384	    public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
385	        if (firstName == null || lastName == null) {
386	            return 0;
387	        }
388	        return (int) ownerRepository.findAll().stream()
389	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
390	                && lastName.equalsIgnoreCase(existing.getLastName()))
391	            .count();
392	    }
393	
394	    /**
395	     * Counts the existing owners whose city matches the given value case-insensitively.
396	     * Used to enforce the per-city capacity rule at creation time.
397	     */
398	    @Override
399	    @Transactional(readOnly = true)
400	    public int countOwnersByCity(String city) throws DataAccessException {
401	        if (city == null) {
402	            return 0;
403	        }
404	        return (int) ownerRepository.findAll().stream()
405	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
406	            .count();
407	    }
408	
409	    /**
410	     * Counts the existing owners whose registration date matches the given value.
411	     * Used to enforce the per-day owner creation limit.
412	     */
413	    @Override
414	    @Transactional(readOnly = true)
415	    public int countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
416	        if (registrationDate == null) {
417	            return 0;
418	        }
419	        return (int) ownerRepository.findAll().stream()
420	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
421	            .count();
422	    }
423	
424	    /**
425	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
426	     * SHA-256 digest over the owner's normalized last name, a {@code '|'} separator and its postcode
427	     * ({@code normalizedLastName + '|' + postcode}). Owners that share a last name and postcode
428	     * therefore map to the same household id automatically, without any explicit linking. Returns
429	     * {@code null} when the last name or postcode is absent or blank, since no household can be
430	     * formed without both.
431	     */
432	    @Override
433	    @Transactional(readOnly = true)
434	    public String computeHouseholdId(Owner owner) throws DataAccessException {
435	        if (owner == null) {
436	            return null;
437	        }
438	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
439	        String postcode = owner.getPostcode();
440	        if (normalizedLastName == null || normalizedLastName.isBlank()
441	            || postcode == null || postcode.isBlank()) {
442	            return null;
443	        }
444	        return sha256UpperHex(normalizedLastName + "|" + postcode, 12);
445	    }
446	
447	    /**
448	     * Whether any existing owner already belongs to the household identified by the given
449	     * (deterministic) household id. This is the single basis for the household-duplicate rule:
450	     * owners that share a last name and postcode share a household id, so a matching existing owner
451	     * means the new owner is a household duplicate. Returns {@code false} when the id is absent.
452	     */
453	    @Override
454	    @Transactional(readOnly = true)
455	    public boolean existsOwnerInHousehold(String householdId) throws DataAccessException {
456	        if (householdId == null || householdId.isBlank()) {
457	            return false;
458	        }
459	        return ownerRepository.findAll().stream()
460	            .filter(existing -> !existing.isDeleted())
461	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
462	    }
463	
464	    /**
465	     * Counts the owners that belong to the household identified by the given (deterministic)
466	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
467	     * the membership-points calculation. Returns {@code 0} when the id is absent.
468	     */
469	    @Override
470	    @Transactional(readOnly = true)
471	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
472	        if (householdId == null || householdId.isBlank()) {
473	            return 0;
474	        }
475	        return (int) ownerRepository.findAll().stream()
476	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
477	            .count();
478	    }
479	
480	    /**
481	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
482	     * runs of whitespace to a single space and lower-casing, so values that differ only in
483	     * whitespace or letter case are treated as equal.
484	     */
485	    private static String normalizeHouseholdField(String value) {
486	        if (value == null) {
487	            return null;
488	        }
489	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
490	    }
491	
492	    /**
493	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
494	     * UTF-8 bytes of {@code seed}.
495	     */
496	    private static String sha256UpperHex(String seed, int length) {
497	        try {
498	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
499	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
500	            StringBuilder sb = new StringBuilder(hash.length * 2);
501	            for (byte b : hash) {
502	                sb.append(String.format("%02X", b));
503	            }
504	            return sb.substring(0, length);
505	        }
506	        catch (NoSuchAlgorithmException e) {
507	            throw new IllegalStateException("SHA-256 not available", e);
508	        }
509	    }
510	
511	    @Override
512	    @Transactional(readOnly = true)
513	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
514	        return ownerRepository.findByLastName(lastName);
515	    }
516	
517	    @Override
518	    @Transactional(readOnly = true)
519	    public Collection<Visit> findVisitsByPetId(int petId) {
520	        return visitRepository.findByPetId(petId);
521	    }
522	
523	    @Override
524	    @Transactional(readOnly = true)
525	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
526	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
527	    }
528	
529	    private <T> T findEntityById(Supplier<T> supplier) {
530	        try {
531	            return supplier.get();
532	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
533	            // Just ignore not found exceptions for Jdbc/Jpa realization
534	            return null;
535	        }
536	    }
537	
538	}
